compile.workshop:
variables {
    global:
        0: arr
        1: result
}

rule ("capture directive without size optimization") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, Index Of Array Value(Global.arr, 0));
        Modify Global Variable(result, Max, 0);
        Modify Global Variable(result, Min, 0);
        Set Global Variable(result, Compare(Global.result, ==, 0));
        Set Global Variable(result, Index Of Array Value(Global.arr, Compare(Global.result, ==, 0)));
    }
}

//Optimize for size enabled
rule ("literal slots precede capture replacement") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, Index Of Array Value(Global.arr, Null));
        Set Global Variable(result, Index Of Array Value(Global.arr, 1));
        Set Global Variable(result, Array Contains(Global.arr, Null));
        Set Global Variable(result, Index Of Array Value(Global.arr, Index Of Array Value(Global.arr, Null)));
        Wait(False, Ignore Condition);
        Create HUD Text(All Players(All Teams), Point Capture Percentage, Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        Modify Global Variable(result, Max, Point Capture Percentage);
        Modify Global Variable(result, Min, Point Capture Percentage);
        Set Global Variable(result, Max(Global.arr, False));
        Set Global Variable(result, Min(Global.arr, False));
        Set Global Variable(result, Compare(Global.result, ==, Null));
        Set Global Variable(result, Index Of Array Value(Global.arr, Compare(Global.result, ==, Null)));
    }
}

rule ("capture comparison condition") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.result == Null;
    }
    actions {
        Set Global Variable(result, 1);
    }
}

//Optimizations disabled
rule ("capture directive with optimizations disabled") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, Max(Global.result, 0));
        Set Global Variable(result, Min(Global.result, 0));
        Set Global Variable(result, Compare(Global.result, ==, 0));
        Set Global Variable(result, Index Of Array Value(Global.arr, Compare(Global.result, ==, 0)));
    }
}

